```javascript
import { Mesh, PlaneGeometry, Vector2, Color, Group, RepeatWrapping, LinearFilter, SRGBColorSpace } from 'three/webgpu';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uniform, uv, texture, vec3, vec2, mix, smoothstep, time, positionLocal, positionWorld, normalLocal, Fn, mul, add, sub, sin, cos, dot, normalize, clamp, length, pow, abs, step, max, min, transformLocalToView } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  group.position.set(-1.25, 1.6, 0);

  // Colors
  const ink = new Color('#16161d');
  const paper = new Color('#e8ecf2');
  const accent = new Color('#ff2a38');
  const surface = new Color('#0b0b10');

  // --- Parallax Plane ---
  const geometry = new PlaneGeometry(2.8, 0.64, 64, 64);
  geometry.rotateX(-Math.PI / 2);

  // Mouse uniform for parallax displacement
  const mouseU = uniform(vec2(0.5, 0.5));

  // Load textures
  const imageTexUniform = uniform(null);
  const depthTexUniform = uniform(null);

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = SRGBColorSpace;
    tex.wrapS = tex.wrapT = RepeatWrapping;
    tex.minFilter = LinearFilter;
    imageTexUniform.value = tex;
  });

  ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
    tex.wrapS = tex.wrapT = RepeatWrapping;
    tex.minFilter = LinearFilter;
    depthTexUniform.value = tex;
  });

  // TSL displacement node
  const displacementNode = Fn(() => {
    const uvCoords = positionLocal.xz.div(vec2(2.8, 0.64)).add(0.5);
    const depthSample = texture(depthTexUniform, uvCoords);
    const depthVal = depthSample.r;

    // Parallax offset from mouse
    const parallaxOffset = sub(mouseU, vec2(0.5, 0.5)).mul(0.04);
    const parallaxShift = texture(depthTexUniform, uvCoords.add(parallaxOffset));
    const displace = mix(depthVal, parallaxShift.r, 0.5).mul(0.12);

    return vec3(0, displace, 0);
  });

  geometry.computeVertexNormals();

  const material = new MeshBasicNodeMaterial({
    colorNode: texture(imageTexUniform, positionLocal.xz.div(vec2(2.8, 0.64)).add(0.5).add(sub(mouseU, vec2(0.5, 0.5)).mul(0.008))),
    displacementNode: displacementNode(),
    roughness: 0.65,
    metalness: 0.15,
  });

  const plane = new Mesh(geometry, material);
  plane.position.y = 0;
  group.add(plane);

  // --- Subtle accent edge line ---
  const edgeGeometry = new PlaneGeometry(2.82, 0.66, 1, 1);
  edgeGeometry.rotateX(-Math.PI / 2);
  const edgeMat = new MeshBasicNodeMaterial({
    color: accent,
    transparent: true,
    opacity: 0.0,
  });
  const edgeMesh = new Mesh(edgeGeometry, edgeMat);
  edgeMesh.position.y = -0.001;
  group.add(edgeMesh);

  // --- Interaction data for hover/click ---
  group.userData.handlers = {};

  // Hover: lift + accent edge
  let hoverTimeline = null;
  group.userData.handlers.onPointerEnter = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(group.position, {
      y: 1.6 + 0.15,
      duration: 0.5,
      ease: 'power3.out',
    }, 0);
    hoverTimeline.to(edgeMat, {
      opacity: 0.7,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
  };

  group.userData.handlers.onPointerLeave = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(group.position, {
      y: 1.6,
      duration: 0.5,
      ease: 'power2.out',
    }, 0);
    hoverTimeline.to(edgeMat, {
      opacity: 0.0,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
  };

  group.userData.handlers.onPointerDown = () => {
    gsap.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(2)',
      onComplete: () => {
        gsap.to(group.scale, {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.3,
          ease: 'power2.out',
        });
      },
    });
  };

  group.userData.handlers.onPointerUp = () => {
    ctx.emit('hub-features.select', {});
  };

  // --- Parallax follow cursor ---
  let rafId = null;
  let targetMouse = new Vector2(0.5, 0.5);
  let currentMouse = new Vector2(0.5, 0.5);

  const updateParallax = () => {
    currentMouse.lerp(targetMouse, 0.04);
    mouseU.value.x = currentMouse.x;
    mouseU.value.y = currentMouse.y;
    rafId = requestAnimationFrame(updateParallax);
  };

  group.userData.handlers.onPointerMove = (event) => {
    targetMouse.x = event.uv.x;
    targetMouse.y = event.uv.y;
  };

  rafId = requestAnimationFrame(updateParallax);

  // --- Cleanup ---
  group.userData.cleanup = () => {
    if (rafId) cancelAnimationFrame(rafId);
    if (hoverTimeline) hoverTimeline.kill();
    geometry.dispose();
    material.dispose();
    edgeMat.dispose();
    edgeGeometry.dispose();
  };

  return group;
}
